[InitializeOnLoad]public static class BeachPromenadeJoin{const string D="Assets/Scenes/Oasis/SouthBeach/BeachDetails";class E{public Vector3 a,b;public int count;}static string K(Vector3 p)=>Mathf.RoundToInt(p.x*100)+","+Mathf.RoundToInt(p.y*100)+","+Mathf.RoundToInt(p.z*100);static List<E> Edges(MeshFilter f){var data=typeof(FinalPNGCityDetails).GetMethod("Read",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{f.sharedMesh});var type=data.GetType();var p=((Vector3[])type.GetField("p").GetValue(data)).Select(f.transform.TransformPoint).ToArray();var ids=(int[])type.GetField("ids").GetValue(data);var map=new Dictionary<string,E>();for(int i=0;i<ids.Length;i+=3){if(Mathf.Abs(Vector3.Cross(p[ids[i+1]]-p[ids[i]],p[ids[i+2]]-p[ids[i]]).normalized.y)<.6f)continue;for(int j=0;j<3;j++){var a=p[ids[i+j]];var b=p[ids[i+(j+1)%3]];string x=K(a),y=K(b),key=string.CompareOrdinal(x,y)<0?x+"/"+y:y+"/"+x;E e;if(map.TryGetValue(key,out e))e.count++;else map[key]=new E{a=a,b=b,count=1};}}return map.Values.Where(e=>e.count==1&&e.a.y>25f&&e.b.y>25f&&(e.a-e.b).sqrMagnitude>.05f).ToList();}static BeachPromenadeJoin(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("BeachPromenadeJoin.request"))return;File.Delete("BeachPromenadeJoin.request");try{Run();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/BeachPromenadeJoin.txt",e.ToString());}}static IEnumerable<E> Split(E e){int n=Mathf.Max(1,Mathf.CeilToInt(Vector3.Distance(e.a,e.b)/3));for(int i=0;i<n;i++)yield return new E{a=Vector3.Lerp(e.a,e.b,(float)i/n),b=Vector3.Lerp(e.a,e.b,(float)(i+1)/n),count=1};}static Vector3 Closest(Vector3 p,E e){var d=e.b-e.a;return e.a+d*Mathf.Clamp01(Vector3.Dot(p-e.a,d)/d.sqrMagnitude);}static void Run(){var s=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var roads=s.GetRootGameObjects().Single(g=>g.name=="Track Roads");Directory.CreateDirectory("FinalEnvironmentRoadBackup/BeforeContinuousPavingJoin");File.Copy(D+"/Joined Beach Paving Gaps.asset","FinalEnvironmentRoadBackup/BeforeContinuousPavingJoin/Previous Join.asset",true);var view=SceneView.lastActiveSceneView;var cameraPos=new Vector3(141.43f,36.25f,-83.49f);var cameraTarget=new Vector3(127.34f,2.14f,-4.63f);File.WriteAllText("FinalEnvironmentRoadReview/GapViewAudit.txt","Active scene="+SceneManager.GetActiveScene().path+"; target scene="+s.path+"; view camera="+cameraPos+" pivot="+cameraTarget);var paving=roads.GetComponentsInChildren<MeshFilter>().Where(f=>!f.name.ToLower().Contains("beach promenade sidewalk joins")&&f.GetComponent<Renderer>()&&f.GetComponent<Renderer>().sharedMaterials.Any(m=>m&&(m.name=="Pathways"||m.name=="Road Atlas"||m.name.StartsWith("City PNG")))).SelectMany(Edges).ToArray();var beach=roads.GetComponentsInChildren<MeshFilter>().Where(f=>f.name=="Outer_MEsh"||f.name=="Canal1").SelectMany(Edges).SelectMany(Split).ToArray();var p=new List<Vector3>();var uv=new List<Vector2>();var ids=new List<int>();int strips=0;var caps=new Dictionary<string,List<Vector3[]>>();foreach(var e in beach){var dir=(e.b-e.a).normalized;var candidates=paving.Where(q=>Mathf.Abs(Vector3.Dot(dir,(q.b-q.a).normalized))>.85f).OrderBy(q=>(Closest((e.a+e.b)*.5f,q)-(e.a+e.b)*.5f).sqrMagnitude).Take(3).ToArray();if(candidates.Length==0)continue;var q=candidates[0];var a=Closest(e.a,q);var b=Closest(e.b,q);float da=new Vector2(a.x-e.a.x,a.z-e.a.z).magnitude,db=new Vector2(b.x-e.b.x,b.z-e.b.z).magnitude;if(Mathf.Max(da,db)>10f||Mathf.Abs(a.y-e.a.y)>3.2f||Mathf.Abs(b.y-e.b.y)>3.2f)continue;var inward=Vector3.Cross(Vector3.up,dir).normalized*1.4f;foreach(var pair in new[]{new[]{e.a,e.a+inward,a},new[]{e.b,e.b+inward,b}}){var key=K(pair[0]);List<Vector3[]> list;if(!caps.TryGetValue(key,out list)){list=new List<Vector3[]>();caps[key]=list;}list.Add(new[]{pair[1],pair[2]});}var points=new[]{e.a+inward,e.b+inward,b,e.a+inward,b,a};for(int i=0;i<points.Length;i+=3){var x=points[i];var y=points[i+1];var z=points[i+2];if(Vector3.Cross(y-x,z-x).y<0){var tmp=y;y=z;z=tmp;}foreach(var v in new[]{x,y,z}){ids.Add(p.Count);p.Add(roads.transform.InverseTransformPoint(v+Vector3.up*.008f));uv.Add(new Vector2(v.x*.25f,v.z*.25f));}}strips++;}foreach(var list in caps.Values.Where(v=>v.Count>1)){for(int j=1;j<list.Count;j++){var v1=list[j-1];var v2=list[j];foreach(var tri in new[]{new[]{v1[0],v1[1],v2[1]},new[]{v1[0],v2[1],v2[0]}}){var cross=Vector3.Cross(tri[1]-tri[0],tri[2]-tri[0]);if(cross.sqrMagnitude<.000000001f)continue;if(cross.y<0){var swap=tri[1];tri[1]=tri[2];tri[2]=swap;}foreach(var v in tri){ids.Add(p.Count);p.Add(roads.transform.InverseTransformPoint(v+Vector3.up*.012f));uv.Add(new Vector2(v.x*.25f,v.z*.25f));}}}}if(strips==0)throw new Exception("No matching shoreline gap found");var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(D+"/Joined Beach Paving Gaps.asset");if(!mesh)mesh=new Mesh{name="Joined beach promenade paving gaps"};mesh.Clear();mesh.indexFormat=p.Count<65535?UnityEngine.Rendering.IndexFormat.UInt16:UnityEngine.Rendering.IndexFormat.UInt32;mesh.SetVertices(p);mesh.SetUVs(0,uv);mesh.SetTriangles(ids,0);mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();mesh.Optimize();if(!AssetDatabase.Contains(mesh))AssetDatabase.CreateAsset(mesh,D+"/Joined Beach Paving Gaps.asset");EditorUtility.SetDirty(mesh);var g=new GameObject("Beach promenade sidewalk joins");g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/3D/Fbx/Materials/Pathways.mat");g.AddComponent<MeshCollider>().sharedMesh=mesh;string path=D+"/Beach Promenade Sidewalk Joins.prefab";bool installed=AssetDatabase.LoadAssetAtPath<GameObject>(path)!=null;PrefabUtility.SaveAsPrefabAsset(g,path);UnityEngine.Object.DestroyImmediate(g);if(!installed)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(path),roads.transform);var prefab=PrefabUtility.LoadPrefabContents("Assets/Scenes/Oasis/FinalEnvironmentRoads/Final Roads.prefab");if(!installed)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(path),prefab.transform);PrefabUtility.SaveAsPrefabAsset(prefab,"Assets/Scenes/Oasis/FinalEnvironmentRoads/Final Roads.prefab");PrefabUtility.UnloadPrefabContents(prefab);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{s,cameraPos,cameraTarget,"Continuous-Beach-Paving-Join"});File.WriteAllText("FinalEnvironmentRoadReview/BeachPromenadeJoin.txt","SUCCESS matched shoreline/back-edge to original Pathways paving; gap joins="+strips+"; triangles="+ids.Count/3+"; matching existing tile texture/world scale; walkable static collider; road prefab and scene saved; no road geometry changed.");}}






